package dev.algorithmlearning.api.courses.application;
import static org.assertj.core.api.Assertions.assertThat;
import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class CourseServiceCourseTest {
 @Test void upsertIsIdempotentAndFilteringKeepsFullDetail(){var repo=new Memory();var service=new CourseService(repo,Clock.fixed(Instant.parse("2026-09-29T00:00:00Z"),ZoneOffset.UTC));var first=service.upsert(List.of(write("leetcode75:one","arrays","Alpha",1))).getFirst();var second=service.upsert(List.of(write("leetcode75:one","arrays","Alpha revised",2))).getFirst();assertThat(second.id()).isEqualTo(first.id());assertThat(service.list("leetcode75","arrays","revised",1,20).items()).extracting(CourseLesson::detail).containsExactly("# full detail\n");assertThat(service.detail("leetcode75:one").orElseThrow().detail()).isEqualTo("# full detail\n");}
 private static CourseImport write(String id,String tag,String title,int order){return new CourseImport("leetcode75","LeetCode 75",1,id,"docs/a.md",title,List.of(tag),"# full detail\n","https://example.test/a","official",order);}
 private static final class Memory implements CourseRepository {final Map<String,CourseCategory> categories=new HashMap<>();final Map<String,CourseLesson> lessons=new HashMap<>();public CourseCategory saveCategory(CourseCategory x){categories.put(x.slug(),x);return x;}public Optional<CourseCategory> findCategoryBySlug(String x){return Optional.ofNullable(categories.get(x));}public CourseLesson saveLesson(CourseLesson x){lessons.put(x.sourceIdentity(),x);return x;}public Optional<CourseLesson> findLessonBySourceIdentity(String x){return Optional.ofNullable(lessons.get(x));}public Optional<CourseLesson> findLessonByIdentity(String x){return findLessonBySourceIdentity(x);}public List<CourseCategory> categories(){return categories.values().stream().sorted(Comparator.comparing(CourseCategory::sortOrder)).toList();}public List<CourseLesson> lessons(String c,String t,String q){return lessons.values().stream().filter(x->c==null||c.equals(x.category().slug())).filter(x->t==null||x.tags().contains(t)).filter(x->q==null||x.englishTitle().toLowerCase().contains(q.toLowerCase())).sorted(Comparator.comparing(CourseLesson::sortOrder)).toList();}}
}
